(7642615, 1241528, 83313, '<td valign="top">Very cool. I''m guessing from the shape of the license plate that this is not located in Corpus Christie Texas.</td>', 'Very cool. I''m guessing from the shape of the license plate that this is not located in Corpus Christie Texas.', '2019-09-30 01:13:55.000000', NULL, 1),
(7642616, 1241531, 83313, '<td valign="top">This plays tricks with my eyes, making me perceive the tower is crooked when it is perfectly straight. Nicely done.</td>', 'This plays tricks with my eyes, making me perceive the tower is crooked when it is perfectly straight. Nicely done.', '2019-09-30 01:15:18.000000', NULL, 1),
